<script setup>
import {usePage,useForm,router,Link} from '@inertiajs/vue3';
import {computed} from 'vue';
import Layout from '../Layout.vue';
const props=defineProps({kind:String,document:Object,supplier:Object,items:Array});const page=usePage();const can=p=>page.props.auth.permissions.includes(p);const receipt=computed(()=>props.kind==='receipts');const form=useForm({id:props.document.id,checklist:{packaging:!!props.document.checklist?.packaging,documents:!!props.document.checklist?.documents,quantity:!!props.document.checklist?.quantity},reason:''});const canEdit=computed(()=>receipt.value&&props.document.status==='pending'&&(can('receive.verify')||(can('receive')&&props.document.created_by===page.props.auth.user.id)));const checked=computed(()=>['packaging','documents','quantity'].every(key=>props.document.checklist?.[key]===true));const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);const status={draft:'Menunggu persetujuan',approved:'Disetujui',partial:'Diterima sebagian',received:'Diterima lengkap',pending:'Menunggu pemeriksaan',posted:'Stok diposting'};
</script>
<template><Layout :title="receipt?'Detail penerimaan':'Detail pesanan'" :module="kind"><div class="page-heading"><div><Link :href="'/'+kind" class="text-link">← Kembali</Link><h1>{{document.number}}</h1><p>{{supplier.name}} · {{status[document.status]}}</p></div><button v-if="!receipt&&document.status==='draft'&&can('purchase.approve')" class="primary" @click="router.post('/actions/purchase.approve',{id:document.id})">Setujui pesanan</button><button v-if="receipt&&document.status==='pending'&&can('receive.verify')" class="primary" :disabled="!checked" @click="router.post('/actions/receipt.verify',{id:document.id})">Verifikasi & posting stok</button></div><div v-for="error in page.props.errors" class="error">{{error}}</div><div class="panel quick-panel"><h3>Dokumen sumber</h3><p>Pemasok: {{supplier.name}} · Izin {{supplier.license}} · Berlaku sampai {{supplier.license_expires}}</p><p v-if="receipt">Faktur: {{document.invoice}} · Jatuh tempo {{document.due_date}}</p><p v-if="receipt&&document.total_cost!==undefined">Total perolehan: {{money(document.total_cost)}}</p></div><section class="panel document-items"><div class="panel-heading"><h3>Item {{receipt?'penerimaan':'pesanan'}}</h3></div><div class="table-scroll"><table><thead><tr><th>Produk</th><th>Jumlah</th><template v-if="receipt"><th>Batch</th><th>Kedaluwarsa</th><th v-if="can('cost')">Biaya per satuan beli</th></template><th v-else>Sudah diposting</th></tr></thead><tbody><tr v-for="(item,index) in items" :key="index"><td>{{item.name}}<small v-if="item.legacy_base_unit" class="block">Data lama: dicatat dalam satuan dasar</small></td><td>{{receipt?item.quantity:item.quantity_base}} {{receipt?item.unit:item.base_unit}}<small v-if="receipt" class="block">{{item.quantity_base}} {{item.base_unit}} dalam ledger</small></td><template v-if="receipt"><td>{{item.batch}}</td><td>{{item.expires_at}}</td><td v-if="can('cost')">{{money(item.unit_cost)}}</td></template><td v-else>{{item.received}} {{item.base_unit}}</td></tr></tbody></table></div></section><section v-if="receipt" class="panel quick-panel document-items"><h3>Hasil pemeriksaan penerimaan</h3><form v-if="canEdit" @submit.prevent="form.post('/actions/receipt.checklist')"><div class="checklist"><label><input v-model="form.checklist.packaging" type="checkbox" :disabled="!canEdit"/>Kemasan sesuai</label><label><input v-model="form.checklist.documents" type="checkbox" :disabled="!canEdit"/>Dokumen sesuai</label><label><input v-model="form.checklist.quantity" type="checkbox" :disabled="!canEdit"/>Jumlah sesuai</label></div><label v-if="canEdit" class="document-items">Alasan/catatan pemeriksaan<textarea v-model="form.reason" required/></label><div v-for="error in form.errors" class="error">{{error}}</div><button v-if="canEdit" class="primary" :disabled="form.processing">Simpan hasil pemeriksaan</button></form><div v-else class="checklist"><span>Kemasan: {{document.checklist?.packaging?'Sesuai':'Belum sesuai'}}</span><span>Dokumen: {{document.checklist?.documents?'Sesuai':'Belum sesuai'}}</span><span>Jumlah: {{document.checklist?.quantity?'Sesuai':'Belum sesuai'}}</span></div><p class="muted-note">Gudang/TTK mencatat hasil pemeriksaan. Apoteker memverifikasi sebelum stok tersedia. Posting stok tidak membayar pemasok.</p></section></Layout></template>
